import { trpc } from "@/lib/trpc";
import { Activity, ArrowDownToLine, ArrowRight, Bot, BrainCircuit, Check, ChevronRight, CircleAlert, Clock3, Command, Crosshair, Database, FileText, FlaskConical, Globe2, Grid3X3, Info, Layers3, MapPinned, Menu, Mic, Network, Orbit, PanelRightClose, Radar, RotateCw, Satellite, ScanSearch, Send, ShieldCheck, Sparkles, UploadCloud, Waves, X, Zap } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

type Mode = "single" | "bi_temporal" | "cross_modal";
type UiMode = Mode | "auto";
type Modality = "optical" | "multispectral" | "sar" | "unknown";
type FileType = "GeoTIFF" | "TIFF" | "PNG" | "JPEG" | "unknown";
type Asset = { assetId: string; fileName: string; fileType: FileType; modality: Modality; width: number | null; height: number | null; bandCount: number | null; crs: string | null; acquisitionDate: string | null; source: string; sampleId: string | null };
type Result = { runId: string; mode: Mode; task: string; status: string; answer: string; confidence: number; confidenceLabel: string; confidenceNote: string; validation: { imageCount: number; modalities: string[]; pairCompatibility: string; warnings: string[]; rejections: string[] }; evidence: Array<{ id: string; title: string; type: string; summary: string; region: string; colour: string }>; selectedTools: Array<{ id: string; name: string; version: string }>; trace: Array<{ label: string; status: string; detail: string; elapsedMs: number }>; provenance: { dataset: string; source: string; retention: string; modelBundle: string; note: string }; reportMarkdown: string };
type BrowserSpeechRecognition = { continuous: boolean; interimResults: boolean; lang: string; start: () => void; stop: () => void; onresult: ((event: { results: ArrayLike<ArrayLike<{ transcript: string }>> }) => void) | null; onerror: ((event: { error: string }) => void) | null; onend: (() => void) | null };
type BrowserSpeechRecognitionConstructor = new () => BrowserSpeechRecognition;

const OPTICAL_IMAGE = "/manus-storage/geosaarthi-optical-terrain_12b5d412.png";
const SAR_IMAGE = "/manus-storage/geosaarthi-sar-radar_37a56f7b.png";
const CHANGE_IMAGE = "/manus-storage/geosaarthi-change-overlay_2f0bcd64.png";

const modeOptions: Array<{ id: UiMode; title: string; signal: string; copy: string; icon: typeof Sparkles }> = [
  { id: "auto", title: "Auto route", signal: "GeoSaarthi decides", copy: "Infer the required workflow from your question and input assets.", icon: Sparkles },
  { id: "single", title: "Single image", signal: "1 observation", copy: "Visual questions, scene description, or region grounding.", icon: ScanSearch },
  { id: "bi_temporal", title: "Bi-temporal", signal: "2 dates", copy: "Compare spatially corresponding observations for visible change.", icon: Activity },
  { id: "cross_modal", title: "Optical + SAR", signal: "2 modalities", copy: "Inspect complementary optical and radar evidence together.", icon: Layers3 },
];

const suggestedQueries = ["What land cover dominates this area?", "Find the water bodies.", "What changed between these dates?", "Compare optical and SAR evidence.", "Highlight flooded areas."];
const analysisStages = ["Validating", "Understanding query", "Selecting specialist", "Processing imagery", "Extracting evidence", "Estimating confidence", "Packaging answer"];
const earthAreas = [
  { id: "coast", name: "Coastal urban corridor", coords: "4°22′N · 2°10′E", demo: "landcover-vqa", x: "57%", y: "46%", note: "Optical scene · water / built-up / agriculture" },
  { id: "delta", name: "River delta watch", coords: "4°19′N · 2°02′E", demo: "water-grounding", x: "38%", y: "56%", note: "Grounding scene · water-body evidence" },
  { id: "growth", name: "East development belt", coords: "4°25′N · 2°17′E", demo: "urban-change", x: "66%", y: "31%", note: "Bi-temporal sample · visible change" },
  { id: "flood", name: "Floodplain fusion sector", coords: "4°15′N · 2°08′E", demo: "flood-fusion", x: "49%", y: "70%", note: "Optical + SAR pair · complementary evidence" },
];
const telemetryFrames = [
  { latitude: "4.22° N", longitude: "2.10° E", heading: "148° SE", nextPass: "04:18", signal: "Nominal" },
  { latitude: "4.31° N", longitude: "2.18° E", heading: "151° SE", nextPass: "03:44", signal: "Nominal" },
  { latitude: "4.39° N", longitude: "2.27° E", heading: "154° SE", nextPass: "03:09", signal: "Nominal" },
];
const missionFeed = ["Benchmark optical scene linked", "SAR companion layer available", "Change-evidence overlay staged", "Model registry heartbeat received", "Trace package format verified"];

function detectMode(query: string): Mode { const q = query.toLowerCase(); if (/change|changed|compare.*date|before|after|temporal/.test(q)) return "bi_temporal"; if (/sar|radar|optical.*sar|flood/.test(q)) return "cross_modal"; return "single"; }
function formatLabel(value: string) { return value.replaceAll("_", " ").replace(/(^|\s)\S/g, (part) => part.toUpperCase()); }
function fileTypeFromName(name: string): FileType { const ext = name.split(".").pop()?.toLowerCase(); if (ext === "tif") return "TIFF"; if (ext === "tiff") return "GeoTIFF"; if (ext === "png") return "PNG"; if (ext === "jpg" || ext === "jpeg") return "JPEG"; return "unknown"; }
function pill(status: string) { if (status === "success" || status === "complete") return "status-pill status-good"; if (status === "warning" || status === "low_confidence" || status === "rejected" || status === "error") return "status-pill status-warn"; return "status-pill status-blue"; }

export default function Home() {
  const [uiMode, setUiMode] = useState<UiMode>("auto");
  const [assets, setAssets] = useState<Asset[]>([]);
  const [query, setQuery] = useState("What land cover dominates this area?");
  const [result, setResult] = useState<Result | null>(null);
  const [activeNav, setActiveNav] = useState("mission");
  const [viewerLayer, setViewerLayer] = useState<"optical" | "sar" | "change">("optical");
  const [overlayOpacity, setOverlayOpacity] = useState(72);
  const [mobileNav, setMobileNav] = useState(false);
  const [isMissionAnimating, setMissionAnimating] = useState(false);
  const [processingStage, setProcessingStage] = useState(0);
  const [earthLayer, setEarthLayer] = useState<"optical" | "sar" | "change">("optical");
  const [earthScale, setEarthScale] = useState(1);
  const [selectedArea, setSelectedArea] = useState(earthAreas[0]);
  const [comparisonMode, setComparisonMode] = useState<"swipe" | "split" | "difference">("swipe");
  const [comparisonPosition, setComparisonPosition] = useState(52);
  const [showChangeEvidence, setShowChangeEvidence] = useState(true);
  const [isListening, setIsListening] = useState(false);
  const [queryHistory, setQueryHistory] = useState<string[]>([]);
  const [telemetryFrame, setTelemetryFrame] = useState(0);
  const uploadRef = useRef<HTMLInputElement>(null);
  const utils = trpc.useUtils();
  const demoCases = trpc.geosaarthi.demoCases.useQuery();
  const registry = trpc.geosaarthi.modelRegistry.useQuery();
  const recentRuns = trpc.geosaarthi.recentRuns.useQuery({ limit: 7 });
  const effectiveMode = useMemo(() => uiMode === "auto" ? detectMode(query) : uiMode, [uiMode, query]);
  const previewInput = useMemo(() => ({ mode: effectiveMode, query: query.trim() || "Describe this scene", assets, demoCaseId: undefined }), [effectiveMode, query, assets]);
  const preview = trpc.geosaarthi.previewAnalysis.useQuery(previewInput, { enabled: assets.length > 0, retry: false });
  const execute = trpc.geosaarthi.executeAnalysis.useMutation({ onError: () => toast.error("Mission control could not complete the analysis.") });

  useEffect(() => {
    if (!isMissionAnimating) return;
    const timer = window.setInterval(() => setProcessingStage((stage) => Math.min(stage + 1, analysisStages.length - 1)), 210);
    return () => window.clearInterval(timer);
  }, [isMissionAnimating]);

  useEffect(() => {
    const timer = window.setInterval(() => setTelemetryFrame((frame) => (frame + 1) % telemetryFrames.length), 3600);
    return () => window.clearInterval(timer);
  }, []);

  function goto(id: string) { setActiveNav(id); setMobileNav(false); document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "start" }); }
  function loadDemo(id: string) { const demo = demoCases.data?.find((item) => item.id === id); if (!demo) return; setUiMode(demo.mode); setAssets(demo.assets as Asset[]); setQuery(demo.query); setResult(null); setViewerLayer(demo.mode === "cross_modal" ? "sar" : demo.mode === "bi_temporal" ? "change" : "optical"); goto("console"); toast.message(`${demo.title} loaded into mission control`); }
  function addFiles(files: FileList | null) { if (!files?.length) return; const limit = effectiveMode === "single" ? 1 : 2; const chosen = Array.from(files).slice(0, limit).map((file, index): Asset => ({ assetId: `local-${Date.now()}-${index}`, fileName: file.name, fileType: fileTypeFromName(file.name), modality: effectiveMode === "cross_modal" ? index === 0 ? "optical" : "sar" : "optical", width: null, height: null, bandCount: null, crs: null, acquisitionDate: effectiveMode === "bi_temporal" ? index === 0 ? "2023-07-01" : "2024-07-01" : "2024-07-09", source: "Local browser upload · metadata only", sampleId: null })); setAssets(chosen); setResult(null); toast.message("Asset metadata queued for validation; raw files stay in this browser session."); }
  function updateAsset(index: number, key: "modality" | "acquisitionDate", value: string) { setAssets((items) => items.map((item, itemIndex) => itemIndex === index ? { ...item, [key]: value } : item)); setResult(null); }
  async function start() {
    if (!assets.length) { toast.error("Load a demo case or select a supported Earth-observation asset first."); return; }
    if (query.trim()) setQueryHistory((items) => [query.trim(), ...items.filter((item) => item !== query.trim())].slice(0, 4));
    setProcessingStage(0);
    setMissionAnimating(true);
    try {
      const [data] = await Promise.all([
        execute.mutateAsync(previewInput),
        new Promise((resolve) => window.setTimeout(resolve, 1550)),
      ]);
      setResult(data as Result);
      void utils.geosaarthi.recentRuns.invalidate();
      toast.success(data.status === "success" ? "Evidence package ready" : "Mission returned a review state");
      window.setTimeout(() => document.getElementById("result")?.scrollIntoView({ behavior: "smooth", block: "start" }), 80);
    } finally {
      setMissionAnimating(false);
    }
  }
  function downloadReport() { if (!result?.reportMarkdown) return; const blob = new Blob([result.reportMarkdown], { type: "text/markdown;charset=utf-8" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `geosaarthi-${result.runId}-intelligence-report.md`; link.click(); URL.revokeObjectURL(url); }
  function resetMission() { setAssets([]); setResult(null); setUiMode("auto"); setQuery("What land cover dominates this area?"); setViewerLayer("optical"); toast.message("New analysis mission initialized"); }
  function makeQueryPrecise() { const trimmed = query.trim(); if (!trimmed) { toast.error("Add a question before requesting guidance."); return; } const base = trimmed.replace(/[.?!]+$/, ""); setQuery(`${base}. State the observable imagery evidence, relevant region, and uncertainty.`); toast.message("Precision guidance added to your query."); }
  function explainRoute() { const modeReason = uiMode === "auto" ? "Auto route inspected your question language." : `You selected ${formatLabel(uiMode)} mode.`; toast.message(`${modeReason} Expected specialist workflow: ${formatLabel(preview.data?.task ?? detectMode(query))}.`); }
  function startVoiceCapture() { const speechWindow = window as unknown as { SpeechRecognition?: BrowserSpeechRecognitionConstructor; webkitSpeechRecognition?: BrowserSpeechRecognitionConstructor }; const SpeechRecognition = speechWindow.SpeechRecognition ?? speechWindow.webkitSpeechRecognition; if (!SpeechRecognition) { toast.error("Voice capture is not supported by this browser. Type or paste your query instead."); return; } const recognition = new SpeechRecognition(); recognition.continuous = false; recognition.interimResults = false; recognition.lang = "en-IN"; recognition.onresult = (event) => { const finalIndex = event.results.length - 1; const transcript = event.results[finalIndex]?.[0]?.transcript?.trim(); if (transcript) { setQuery(transcript); toast.success("Voice query captured. Review it before analysis."); } }; recognition.onerror = (event) => { const reason = event.error === "not-allowed" ? "Microphone permission was not granted." : "Voice capture could not complete."; toast.error(`${reason} You can continue by typing your query.`); }; recognition.onend = () => setIsListening(false); try { setIsListening(true); recognition.start(); } catch { setIsListening(false); toast.error("Voice capture is already active or unavailable. Type your query instead."); } }

  const nav = [{ id: "mission", label: "Mission", icon: Globe2 }, { id: "earth", label: "Earth explorer", icon: MapPinned }, { id: "time-machine", label: "Time machine", icon: Activity }, { id: "console", label: "Command center", icon: Command }, { id: "result", label: "Evidence", icon: Crosshair }, { id: "workflows", label: "AI workflows", icon: BrainCircuit }, { id: "observatory", label: "Observatory", icon: Activity }, { id: "judge", label: "Judge mode", icon: ShieldCheck }];
  const activeViewer = viewerLayer === "optical" ? OPTICAL_IMAGE : viewerLayer === "sar" ? SAR_IMAGE : CHANGE_IMAGE;
  const validation = preview.data?.validation;
  const telemetry = telemetryFrames[telemetryFrame];
  const recordedRuns = recentRuns.data ?? [];
  const successfulRuns = recordedRuns.filter((run) => run.status === "success").length;
  const reviewRuns = recordedRuns.filter((run) => run.status !== "success").length;
  const averageConfidence = recordedRuns.length ? Math.round(recordedRuns.reduce((total, run) => total + run.overallConfidence, 0) / recordedRuns.length) : null;

  return <div className="mission-shell">
    <header className="desk-nav"><div className="mx-auto flex max-w-[1500px] items-center justify-between px-5 py-3 md:px-8"><button onClick={() => goto("mission")} className="flex items-center gap-3 text-left"><span className="grid size-9 place-items-center rounded-full border border-cyan-200/40 bg-cyan-300/10 text-cyan-100 glow-cyan"><Orbit className="size-5" /></span><span><span className="block text-base font-bold tracking-tight text-white">GeoSaarthi</span><span className="mission-mono block text-[8px] tracking-[.19em] text-cyan-200/65">Earth intelligence system</span></span></button><nav className="hidden items-center gap-1 lg:flex">{nav.map((item) => <button key={item.id} onClick={() => goto(item.id)} className={`flex items-center gap-2 px-3 py-2 text-xs font-semibold transition-colors ${activeNav === item.id ? "text-cyan-200" : "text-slate-400 hover:text-slate-100"}`}><item.icon className="size-3.5" />{item.label}</button>)}</nav><div className="flex items-center gap-3"><span className="hidden items-center gap-2 mission-mono text-[9px] font-bold tracking-wider text-emerald-200 sm:flex"><i className="signal-dot" /> AI online</span><button className="mission-button min-h-9 px-3 text-[10px]" onClick={resetMission}><RotateCw className="size-3.5" /> <span className="hidden sm:inline">New mission</span></button><button aria-label="Open navigation" onClick={() => setMobileNav((value) => !value)} className="grid size-9 place-items-center border border-cyan-100/20 lg:hidden">{mobileNav ? <X className="size-4" /> : <Menu className="size-4" />}</button></div></div>{mobileNav ? <div className="border-t border-cyan-100/10 bg-[#061727] px-5 py-3 lg:hidden">{nav.map((item) => <button key={item.id} onClick={() => goto(item.id)} className="flex w-full items-center gap-3 px-1 py-3 text-left text-sm text-slate-300"><item.icon className="size-4 text-cyan-200" />{item.label}<ChevronRight className="ml-auto size-4" /></button>)}</div> : null}</header>

    <main>
      <section id="mission" className="relative isolate overflow-hidden border-b border-cyan-100/10 scroll-mt-16"><div className="mission-grid absolute inset-0 opacity-55" /><div className="mission-noise absolute inset-0" /><div className="absolute -left-36 top-32 size-[29rem] rounded-full bg-cyan-400/12 blur-[130px]" /><div className="absolute -right-28 bottom-0 size-[31rem] rounded-full bg-violet-600/10 blur-[140px]" /><div className="relative mx-auto grid max-w-[1500px] gap-10 px-5 py-20 md:px-8 lg:grid-cols-[1.03fr_.97fr] lg:items-center lg:py-28"><div><p className="mission-kicker flex items-center gap-2"><span className="signal-dot" /> SatQuery AI / SIH26167</p><h1 className="mission-heading mt-6 max-w-3xl text-white">Ask anything.<br /><span className="bg-gradient-to-r from-cyan-200 via-sky-300 to-violet-300 bg-clip-text text-transparent">Understand Earth.</span></h1><p className="mission-copy mt-7 max-w-xl text-base md:text-lg">An evidence-first Earth-observation assistant that validates remote-sensing inputs, selects a specialist workflow, and exposes the route from imagery to answer.</p><div className="mt-8 flex flex-wrap gap-3"><button className="mission-button mission-button-primary" onClick={() => goto("console")}>Start analysis <ArrowRight className="size-4" /></button><button className="mission-button" onClick={() => goto("demos")}>Explore demo <FlaskConical className="size-4" /></button></div><div className="mt-10 grid max-w-xl grid-cols-2 gap-px border border-cyan-100/15 bg-cyan-100/15 sm:grid-cols-4">{[{ v: "4", l: "demo paths" }, { v: "3", l: "input modes" }, { v: "5", l: "specialists" }, { v: "100%", l: "traceable" }].map((stat) => <div key={stat.l} className="bg-[#091b2c]/90 px-3 py-4"><p className="text-xl font-bold text-white">{stat.v}</p><p className="mission-mono mt-1 text-[8px] font-semibold uppercase tracking-[.12em] text-slate-400">{stat.l}</p></div>)}</div></div>
        <div className="relative mx-auto w-full max-w-[620px]" aria-label="Orbital Earth intelligence visual"><div className="relative aspect-square"><div className="orbit orbit-one" /><div className="orbit orbit-two" /><div className="orbit orbit-three" /><div className="satellite left-[2%] top-[58%]"><i className="satellite-panel" /><i className="satellite-body" /><i className="satellite-panel" /></div><div className="absolute inset-[11%] overflow-hidden rounded-full border border-cyan-100/35 bg-[#0b2336] shadow-[0_0_100px_rgba(59,194,226,.24)]"><img src={OPTICAL_IMAGE} alt="Optical satellite image of a coastal landscape" className="size-full object-cover opacity-90" /><div className="absolute inset-0 bg-[radial-gradient(circle_at_31%_19%,transparent_4%,rgba(4,18,31,.1)_38%,rgba(4,18,31,.88)_75%)]" /><div className="radar-cone" /><div className="absolute inset-0 border-[14px] border-[#081928]/35 rounded-full" /></div><div className="absolute left-[2%] top-[19%] border border-cyan-200/25 bg-[#071a2a]/90 px-3 py-2 backdrop-blur"><p className="mission-mono text-[8px] tracking-widest text-slate-400">Imaging status</p><p className="mt-1 flex items-center gap-2 text-xs font-bold text-cyan-100"><i className="signal-dot" /> Acquiring</p></div><div className="absolute right-[0%] bottom-[18%] border border-cyan-200/25 bg-[#071a2a]/90 px-3 py-2 backdrop-blur"><p className="mission-mono text-[8px] tracking-widest text-slate-400">Orbit lock</p><p className="mt-1 text-xs font-bold text-amber-200">98.7% stable</p></div><div className="absolute bottom-[3%] left-1/2 -translate-x-1/2 border border-violet-200/25 bg-[#0a162b]/90 px-3 py-2 text-center backdrop-blur"><p className="mission-mono text-[8px] tracking-[.14em] text-violet-200">Evidence layer active</p></div></div></div></div></section>

      <section className="border-b border-cyan-100/10 bg-[#061828]"><div className="mx-auto grid max-w-[1500px] gap-3 px-5 py-5 md:grid-cols-3 md:px-8"><div className="flex items-center gap-4 border border-cyan-100/10 bg-cyan-300/[.035] p-4"><Satellite className="size-5 text-cyan-200" /><div><p className="mission-mono text-[9px] tracking-widest text-slate-400">Mission simulator</p><p className="mt-1 text-sm font-semibold">Sentinel-class optical + SAR</p></div></div><div className="flex items-center gap-4 border border-cyan-100/10 bg-cyan-300/[.035] p-4"><Radar className="size-5 text-cyan-200" /><div><p className="mission-mono text-[9px] tracking-widest text-slate-400">Downlink status</p><p className="mt-1 text-sm font-semibold">Benchmark assets available</p></div></div><div className="flex items-center gap-4 border border-cyan-100/10 bg-cyan-300/[.035] p-4"><ShieldCheck className="size-5 text-emerald-200" /><div><p className="mission-mono text-[9px] tracking-widest text-slate-400">Responsible AI</p><p className="mt-1 text-sm font-semibold">Evidence and uncertainty visible</p></div></div></div></section>

      <section id="earth" className="mission-grid scroll-mt-16 border-b border-cyan-100/10 px-5 py-20 md:px-8"><div className="mx-auto max-w-[1500px]"><div className="mb-8 flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><p className="mission-kicker">Bounded Earth explorer</p><h2 className="mission-section-heading mt-3 text-white">Choose an area. Start a mission.</h2><p className="mission-copy mt-4 max-w-2xl">Explore selected benchmark sectors through a visual Earth interface, then send one sector into the analysis console. This is a supplied-asset simulator rather than a live satellite feed or a production GIS service.</p></div><span className="status-pill status-warn"><CircleAlert className="size-3" /> Demo simulation</span></div><div className="grid gap-5 xl:grid-cols-[1.05fr_.62fr_.43fr]"><div className="mission-panel overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-cyan-100/10 p-4"><div className="flex flex-wrap gap-2">{([{ id: "optical", label: "Optical", icon: Globe2 }, { id: "sar", label: "SAR", icon: Radar }, { id: "change", label: "Change", icon: Waves }] as const).map((layer) => <button key={layer.id} onClick={() => setEarthLayer(layer.id)} className={`status-pill ${earthLayer === layer.id ? "status-blue" : "status-muted"}`}><layer.icon className="size-3" /> {layer.label}</button>)}</div><div className="flex items-center gap-2"><button aria-label="Zoom out Earth explorer" onClick={() => setEarthScale((scale) => Math.max(.78, Number((scale - .08).toFixed(2))))} className="grid size-7 place-items-center border border-cyan-100/20 text-cyan-100">−</button><span className="mission-mono text-[9px] text-slate-500">{Math.round(earthScale * 100)}%</span><button aria-label="Zoom in Earth explorer" onClick={() => setEarthScale((scale) => Math.min(1.22, Number((scale + .08).toFixed(2))))} className="grid size-7 place-items-center border border-cyan-100/20 text-cyan-100">+</button></div></div><div className="mission-grid relative aspect-[1.36/1] overflow-hidden bg-[#020c15]"><img src={earthLayer === "optical" ? OPTICAL_IMAGE : earthLayer === "sar" ? SAR_IMAGE : CHANGE_IMAGE} alt={`${earthLayer} exploration scene`} className="size-full object-cover transition-transform duration-500" style={{ transform: `scale(${earthScale})` }} />{earthAreas.map((area) => <button key={area.id} aria-label={`Select ${area.name}`} onClick={() => setSelectedArea(area)} className="absolute z-10 grid size-7 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full border border-cyan-100/70 bg-cyan-300/20 text-cyan-100 shadow-[0_0_18px_rgba(112,228,255,.75)] transition-transform hover:scale-125" style={{ left: area.x, top: area.y }}><span className={`size-2 rounded-full ${selectedArea.id === area.id ? "bg-amber-200" : "bg-cyan-200"}`} /></button>)}<div className="absolute left-4 top-4 border border-cyan-100/20 bg-[#061827]/85 px-3 py-2 backdrop-blur"><p className="mission-mono text-[8px] tracking-widest text-slate-400">AOI / {selectedArea.id}</p><p className="mt-1 text-xs font-bold text-cyan-100">{selectedArea.coords}</p></div><div className="absolute bottom-4 right-4 border border-cyan-100/20 bg-[#061827]/85 px-3 py-2 backdrop-blur"><p className="mission-mono text-[8px] tracking-widest text-slate-400">Layer</p><p className="mt-1 text-xs font-bold text-cyan-100">{formatLabel(earthLayer)}</p></div></div><div className="grid grid-cols-3 divide-x divide-cyan-100/10 border-t border-cyan-100/10"><div className="p-3"><p className="mission-mono text-[8px] text-slate-500">AOI</p><p className="mt-1 text-xs font-bold text-white">{selectedArea.id.toUpperCase()}</p></div><div className="p-3"><p className="mission-mono text-[8px] text-slate-500">Controls</p><p className="mt-1 text-xs font-bold text-white">Layer / Zoom</p></div><div className="p-3"><p className="mission-mono text-[8px] text-slate-500">Source</p><p className="mt-1 text-xs font-bold text-white">Benchmark</p></div></div></div><div className="mission-panel p-5"><p className="mission-kicker">Area-of-interest roster</p><div className="mt-4 space-y-2">{earthAreas.map((area) => <button key={area.id} onClick={() => setSelectedArea(area)} className={`block w-full border p-3 text-left transition-colors ${selectedArea.id === area.id ? "border-cyan-200/50 bg-cyan-300/[.1]" : "border-cyan-100/10 bg-[#071827]/45 hover:border-cyan-100/35"}`}><div className="flex items-center justify-between gap-3"><p className="text-xs font-bold text-slate-100">{area.name}</p><MapPinned className="size-3.5 text-cyan-200" /></div><p className="mission-mono mt-2 text-[8px] tracking-wide text-slate-500">{area.coords}</p><p className="mt-2 text-xs leading-5 text-slate-400">{area.note}</p></button>)}</div></div><div className="mission-panel flex flex-col p-5"><div><p className="mission-kicker">Selected mission area</p><h3 className="mt-3 text-xl font-bold tracking-tight text-white">{selectedArea.name}</h3><p className="mission-mono mt-2 text-[9px] tracking-widest text-cyan-200">{selectedArea.coords}</p><p className="mission-copy mt-5 text-xs">{selectedArea.note}. Use this sector to preload a guided demo, preserving the declared workflow and asset metadata.</p></div><div className="mt-auto border-t border-cyan-100/10 pt-4"><button className="mission-button mission-button-primary w-full" onClick={() => loadDemo(selectedArea.demo)}>Analyze captured region <ArrowRight className="size-4" /></button><p className="mt-3 text-[10px] leading-4 text-slate-500">The control starts a benchmark scenario; it does not retrieve live imagery.</p></div></div></div></div></section>

      <section id="time-machine" className="scroll-mt-16 border-b border-cyan-100/10 bg-[#061727] px-5 py-20 md:px-8"><div className="mx-auto max-w-[1500px]"><div className="mb-8 flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><p className="mission-kicker">Bi-temporal time machine</p><h2 className="mission-section-heading mt-3 text-white">Put two observations on the same timeline.</h2><p className="mission-copy mt-4 max-w-2xl">Move across a scripted before/after visual comparison, switch to a difference view, and examine the marked visual evidence before loading the change-analysis workflow.</p></div><div className="flex flex-wrap gap-2"><span className="status-pill status-warn"><CircleAlert className="size-3" /> Scripted comparison</span><button className="mission-button" onClick={() => loadDemo("urban-change")}>Load change mission <ArrowRight className="size-4" /></button></div></div><div className="grid gap-5 xl:grid-cols-[1.18fr_.82fr]"><div className="mission-panel overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-cyan-100/10 p-4"><div className="flex flex-wrap gap-2">{(["swipe", "split", "difference"] as const).map((mode) => <button key={mode} onClick={() => setComparisonMode(mode)} className={`status-pill ${comparisonMode === mode ? "status-blue" : "status-muted"}`}>{formatLabel(mode)}</button>)}</div><button onClick={() => setShowChangeEvidence((value) => !value)} className={`status-pill ${showChangeEvidence ? "status-good" : "status-muted"}`}><Crosshair className="size-3" /> Evidence {showChangeEvidence ? "on" : "off"}</button></div><div className="relative aspect-[1.45/1] overflow-hidden bg-[#020d17]">{comparisonMode === "split" ? <div className="grid size-full grid-cols-2 gap-px bg-cyan-100/20"><div className="relative overflow-hidden"><img src={OPTICAL_IMAGE} alt="Earlier benchmark optical observation" className="size-full object-cover" /><span className="absolute left-3 top-3 bg-[#061827]/85 px-2 py-1 mission-mono text-[9px] text-cyan-100">Before / 2023</span></div><div className="relative overflow-hidden"><img src={CHANGE_IMAGE} alt="Later scripted change observation" className="size-full object-cover" /><span className="absolute left-3 top-3 bg-[#061827]/85 px-2 py-1 mission-mono text-[9px] text-amber-200">After / 2024</span></div></div> : <><img src={comparisonMode === "difference" ? CHANGE_IMAGE : OPTICAL_IMAGE} alt="Bi-temporal comparison base observation" className="size-full object-cover" />{comparisonMode === "swipe" ? <div className="absolute inset-y-0 left-0 overflow-hidden border-r-2 border-cyan-100" style={{ width: `${comparisonPosition}%` }}><img src={CHANGE_IMAGE} alt="Later scripted change observation" className="size-full max-w-none object-cover" style={{ width: `${10000 / comparisonPosition}%` }} /><span className="absolute left-3 top-3 bg-[#061827]/85 px-2 py-1 mission-mono text-[9px] text-amber-200">After / 2024</span></div> : null}{comparisonMode === "difference" ? <div className="absolute inset-0 bg-cyan-400/10 mix-blend-screen" /> : null}<span className="absolute right-3 top-3 bg-[#061827]/85 px-2 py-1 mission-mono text-[9px] text-cyan-100">{comparisonMode === "difference" ? "Change evidence view" : "Before / 2023"}</span></>}{showChangeEvidence ? <div className="absolute left-[34%] top-[30%] h-[36%] w-[31%] border-2 border-amber-200 bg-amber-300/10 shadow-[0_0_28px_rgba(255,189,105,.28)]"><span className="absolute -top-7 left-0 whitespace-nowrap bg-amber-200 px-2 py-1 mission-mono text-[8px] font-bold text-[#2a1400]">Observed-change region</span></div> : null}<div className="absolute bottom-0 inset-x-0 border-t border-cyan-100/20 bg-[#041523]/90 px-4 py-3 backdrop-blur"><input aria-label="Move through time comparison" type="range" min="0" max="100" value={comparisonPosition} onChange={(event) => setComparisonPosition(Number(event.target.value))} className="w-full accent-cyan-200" /><div className="mt-2 flex items-center justify-between mission-mono text-[8px] tracking-widest text-slate-400"><span>2023-07-01</span><span className="text-cyan-100">{comparisonPosition}% comparison position</span><span>2024-07-01</span></div></div></div><div className="grid grid-cols-3 divide-x divide-cyan-100/10 border-t border-cyan-100/10"><div className="p-3"><p className="mission-mono text-[8px] text-slate-500">Visual state</p><p className="mt-1 text-xs font-bold text-white">{formatLabel(comparisonMode)}</p></div><div className="p-3"><p className="mission-mono text-[8px] text-slate-500">Evidence</p><p className="mt-1 text-xs font-bold text-white">{showChangeEvidence ? "Marked" : "Hidden"}</p></div><div className="p-3"><p className="mission-mono text-[8px] text-slate-500">Interpretation</p><p className="mt-1 text-xs font-bold text-white">Human review</p></div></div></div><div className="mission-panel p-5"><p className="mission-kicker">Change brief</p><h3 className="mt-3 text-xl font-bold tracking-tight text-white">Observed visual difference, not inferred cause.</h3><div className="mt-5 space-y-3"><div className="border border-cyan-100/10 bg-[#071827]/70 p-3"><p className="mission-mono text-[9px] tracking-widest text-cyan-200">What can be stated</p><p className="mt-2 text-xs leading-5 text-slate-300">The marked region has a different visual pattern between the two scripted observations and is routed to the bi-temporal change workflow.</p></div><div className="border border-amber-200/20 bg-amber-300/[.06] p-3"><p className="mission-mono text-[9px] tracking-widest text-amber-200">What cannot be stated</p><p className="mt-2 text-xs leading-5 text-amber-100/75">The interface does not infer cause, ownership, damage, or real-world impact from the visual difference alone.</p></div></div><div className="mt-5 border-t border-cyan-100/10 pt-4"><p className="mission-mono text-[9px] tracking-widest text-slate-500">Evidence sequence</p><ol className="mt-3 space-y-3">{["Inspect input pair compatibility", "Compare spatially corresponding observations", "Mark an observed-change candidate", "Route to specialist and report uncertainty"].map((step, index) => <li key={step} className="flex gap-3"><span className="grid size-5 shrink-0 place-items-center border border-cyan-100/30 mission-mono text-[9px] text-cyan-100">0{index + 1}</span><p className="pt-0.5 text-xs leading-5 text-slate-400">{step}</p></li>)}</ol></div></div></div></div></section>

      <section id="console" className="mission-grid scroll-mt-16 px-5 py-20 md:px-8"><div className="mx-auto max-w-[1500px]"><div className="mb-8 flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><p className="mission-kicker">Interactive satellite control center</p><h2 className="mission-section-heading mt-3 max-w-2xl text-white">Run a traceable analysis mission.</h2><p className="mission-copy mt-4 max-w-2xl">Choose an analysis mode, bring a benchmark case or supported image metadata, and submit a supported question. Validation completes before specialist execution begins.</p></div><div className="flex flex-wrap gap-2"><span className="status-pill status-blue"><Zap className="size-3" /> {formatLabel(effectiveMode)} detected</span><span className="status-pill status-good"><Check className="size-3" /> Metadata-only storage</span></div></div>
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1.14fr)_minmax(330px,.62fr)]"><div className="mission-panel p-4 sm:p-6"><div className="flex items-center justify-between"><div><p className="mission-kicker">01 / Intelligence mode</p><h3 className="mt-2 text-lg font-bold text-white">Tell the system how to see.</h3></div><span className="mission-mono text-[9px] text-slate-500">Mode selector</span></div><div className="mt-5 grid gap-2 sm:grid-cols-2 xl:grid-cols-4">{modeOptions.map((option) => <button key={option.id} onClick={() => { setUiMode(option.id); setAssets([]); setResult(null); }} className={`mode-card ${uiMode === option.id ? "mode-card-active" : ""}`}><div className="flex items-center justify-between"><option.icon className="size-5 text-cyan-200" /><span className="mission-mono text-[8px] text-slate-500">{option.signal}</span></div><p className="mt-7 text-sm font-bold text-white">{option.title}</p><p className="mt-2 text-xs leading-5 text-slate-400">{option.copy}</p></button>)}</div><div className="mt-7 flex items-center justify-between"><div><p className="mission-kicker">02 / Satellite asset ingestion</p><p className="mt-2 text-sm text-slate-300">Drop GeoTIFF/TIFF or approved benchmark PNG/JPEG.</p></div><button className="mission-button" onClick={() => uploadRef.current?.click()}><UploadCloud className="size-4" /> Add asset</button><input ref={uploadRef} type="file" accept=".tif,.tiff,.png,.jpeg,.jpg" multiple={effectiveMode !== "single"} onChange={(event) => addFiles(event.target.files)} className="hidden" /></div><div className="scan-drop mission-grid relative mt-3 overflow-hidden p-4">{assets.length === 0 ? <div className="relative z-10 flex min-h-[136px] flex-col items-center justify-center text-center"><UploadCloud className="size-7 text-cyan-200/75" /><p className="mission-mono mt-3 text-xs font-bold tracking-[.16em] text-cyan-100">Drop satellite data here</p><p className="mt-2 max-w-md text-xs leading-5 text-slate-400">Or begin with one of the scripted public benchmark missions below. Uploads remain in this browser workspace; only metadata and trace records persist.</p></div> : <div className="relative z-10 space-y-2">{assets.map((asset, index) => <div key={asset.assetId} className="asset-row p-3"><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 gap-3"><FileText className="mt-0.5 size-4 shrink-0 text-cyan-200" /><div className="min-w-0"><p className="truncate text-sm font-semibold text-slate-100">{asset.fileName}</p><p className="mission-mono mt-1 text-[9px] tracking-wide text-slate-500">{asset.fileType} · {asset.source} · {asset.crs ?? "CRS not attached"}</p></div></div><button aria-label={`Remove ${asset.fileName}`} onClick={() => setAssets((items) => items.filter((_, itemIndex) => itemIndex !== index))} className="text-slate-500 hover:text-amber-200"><X className="size-4" /></button></div><div className="mt-3 grid gap-2 sm:grid-cols-2"><label className="mission-mono text-[9px] tracking-widest text-slate-500">Declared modality<select value={asset.modality} onChange={(event) => updateAsset(index, "modality", event.target.value)} className="terminal-input mt-1 py-2 text-xs"><option value="optical">Optical</option><option value="multispectral">Multispectral</option><option value="sar">SAR</option><option value="unknown">Unknown</option></select></label><label className="mission-mono text-[9px] tracking-widest text-slate-500">Acquisition date<select value={asset.acquisitionDate ?? "unknown"} onChange={(event) => updateAsset(index, "acquisitionDate", event.target.value === "unknown" ? "" : event.target.value)} className="terminal-input mt-1 py-2 text-xs"><option value="2023-07-01">2023-07-01</option><option value="2024-07-09">2024-07-09</option><option value="2024-07-01">2024-07-01</option><option value="unknown">Unknown</option></select></label></div></div>)}</div>}</div><div className="mt-3 flex gap-3 border border-cyan-100/10 bg-cyan-300/[.045] p-3 text-xs leading-5 text-slate-400"><ShieldCheck className="size-4 shrink-0 text-emerald-200" />Raw image bytes are not placed in the database. GeoSaarthi stores run metadata, evidence references, model details, and the execution trace only.</div>
            <div className="mt-7 border-t border-cyan-100/10 pt-5"><div className="flex items-center justify-between"><div><p className="mission-kicker">03 / AI command</p><p className="mt-2 text-sm font-semibold text-white">What do you want to know?</p></div><span className="mission-mono text-[9px] text-slate-500">{query.length}/500</span></div><div className="mt-3 flex flex-col gap-3 sm:flex-row"><textarea value={query} onChange={(event) => setQuery(event.target.value)} maxLength={500} className="terminal-input min-h-[92px] resize-none" placeholder="Ask anything about this satellite image…" /><div className="flex gap-2 sm:flex-col"><button aria-label="Capture voice query" title="Capture voice query" onClick={startVoiceCapture} className={`mission-button min-w-11 px-3 ${isListening ? "border-cyan-200 bg-cyan-300/15 text-cyan-100" : ""}`}><Mic className={`size-4 ${isListening ? "animate-pulse" : ""}`} /><span className="hidden sm:inline">{isListening ? "Listening" : "Voice"}</span></button><button onClick={start} disabled={isMissionAnimating || execute.isPending || !assets.length} className="mission-button mission-button-primary shrink-0">{isMissionAnimating ? <Clock3 className="size-4 animate-spin" /> : <Send className="size-4" />}{isMissionAnimating ? "Processing" : "Run analysis"}</button></div></div><div className="mt-3 flex flex-wrap gap-2">{suggestedQueries.map((suggestion) => <button key={suggestion} onClick={() => setQuery(suggestion)} className="chip">{suggestion}</button>)}</div><div className="mt-3 flex flex-wrap items-center gap-2 border-t border-cyan-100/10 pt-3"><span className="mission-mono text-[9px] tracking-widest text-slate-500">Query support</span><button onClick={makeQueryPrecise} className="chip">Make precise</button><button onClick={explainRoute} className="chip">Why this route?</button>{queryHistory.length ? <><span className="mission-mono ml-1 text-[9px] tracking-widest text-slate-500">Recent</span>{queryHistory.map((item) => <button key={item} title={item} onClick={() => setQuery(item)} className="max-w-48 truncate chip">{item}</button>)}</> : null}</div></div>
            <div className="mt-5 border border-cyan-100/12 bg-[#051725]/75 p-3"><div className="flex items-center justify-between"><p className="mission-mono text-[9px] font-bold tracking-widest text-cyan-100">Mission progress</p><span className={isMissionAnimating ? "status-pill status-blue" : "status-pill status-muted"}>{isMissionAnimating ? `Stage ${Math.min(processingStage + 1, analysisStages.length)}/${analysisStages.length}` : result ? "Trace ready" : "Standing by"}</span></div><div className="mt-4 grid grid-cols-1 gap-2 sm:grid-cols-2 xl:grid-cols-4">{analysisStages.map((stage, index) => { const state = isMissionAnimating ? index < processingStage ? "complete" : index === processingStage ? "active" : "queued" : result ? "complete" : "queued"; return <div key={stage} className={`flex items-center gap-2 border px-2.5 py-2 ${state === "complete" ? "border-emerald-200/20 bg-emerald-300/[.06]" : state === "active" ? "border-cyan-200/50 bg-cyan-300/[.1]" : "border-cyan-100/10 bg-[#081b2c]/65"}`}><span className={`grid size-4 place-items-center rounded-full mission-mono text-[8px] font-bold ${state === "complete" ? "bg-emerald-200 text-[#07231a]" : state === "active" ? "bg-cyan-200 text-[#061522]" : "bg-slate-700 text-slate-300"}`}>{state === "complete" ? <Check className="size-3" /> : index + 1}</span><span className={`mission-mono text-[8px] tracking-wide ${state === "queued" ? "text-slate-500" : "text-slate-100"}`}>{stage}</span></div>; })}</div></div></div>
          <aside className="mission-panel overflow-hidden"><div className="border-b border-cyan-100/10 p-5"><p className="mission-kicker">System checks</p><h3 className="mt-2 text-lg font-bold text-white">Validation radar</h3></div><div className="p-5">{!assets.length ? <div className="flex min-h-[470px] flex-col justify-between"><div className="rounded border border-dashed border-cyan-100/20 bg-[#071828]/75 p-4"><Radar className="size-6 text-amber-200" /><p className="mt-4 text-sm font-bold text-white">Awaiting Earth-observation asset</p><p className="mission-copy mt-2 text-xs">Load a public benchmark mission or add asset metadata to inspect file type, modality, dates, dimensions, CRS, and pair compatibility.</p></div><div className="space-y-3">{["File integrity", "Band structure", "Spatial alignment", "Workflow compatibility"].map((label) => <div key={label} className="flex items-center justify-between border-b border-cyan-100/10 pb-3"><span className="mission-mono text-[10px] tracking-wider text-slate-500">{label}</span><span className="status-pill status-muted">Pending</span></div>)}</div></div> : <div><div className="flex items-center justify-between"><span className={validation?.valid ? "status-pill status-good" : "status-pill status-warn"}>{validation?.valid ? <Check className="size-3" /> : <CircleAlert className="size-3" />}{validation?.valid ? "Asset verified" : "Input review"}</span><span className="mission-mono text-[9px] text-slate-500">{validation?.imageCount ?? 0} asset(s)</span></div><div className="mt-5 space-y-0">{[{ l: "Format", v: assets.map((asset) => asset.fileType).join(" / ") }, { l: "Modality", v: validation?.modalities.join(" / ") ?? "Inspecting" }, { l: "Pair", v: formatLabel(validation?.pairCompatibility ?? "not applicable") }, { l: "Detected task", v: formatLabel(preview.data?.task ?? "inspecting") }].map((item) => <div key={item.l} className="flex items-center justify-between gap-3 border-b border-cyan-100/10 py-3"><span className="mission-mono text-[9px] tracking-widest text-slate-500">{item.l}</span><span className="text-right text-xs font-semibold text-slate-200">{item.v}</span></div>)}</div>{validation?.warnings.length ? <div className="mt-5 border border-amber-200/20 bg-amber-300/[.07] p-3"><p className="flex items-center gap-2 text-xs font-bold text-amber-100"><CircleAlert className="size-3.5" /> Analyst review suggested</p><ul className="mt-2 space-y-1 text-xs leading-5 text-amber-100/70">{validation.warnings.map((item) => <li key={item}>• {item}</li>)}</ul></div> : null}{validation?.rejections.length ? <div className="mt-5 border border-red-300/20 bg-red-300/[.07] p-3"><p className="flex items-center gap-2 text-xs font-bold text-red-100"><CircleAlert className="size-3.5" /> Workflow blocked</p><ul className="mt-2 space-y-1 text-xs leading-5 text-red-100/70">{validation.rejections.map((item) => <li key={item}>• {item}</li>)}</ul></div> : null}<div className="mt-5 border border-cyan-100/10 bg-cyan-300/[.04] p-3"><p className="mission-mono text-[9px] tracking-widest text-cyan-200">Expected route</p><p className="mt-2 text-sm font-bold text-white">{formatLabel(preview.data?.task ?? "Classifying query")}</p><p className="mt-1 text-xs leading-5 text-slate-400">The selected mode, query language, and available modality determine the specialist workflow.</p></div></div>}</div></aside></div></div></section>

      <section id="result" className="scroll-mt-16 border-y border-cyan-100/10 bg-[#061727] px-5 py-20 md:px-8"><div className="mx-auto max-w-[1500px]"><div className="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="mission-kicker">Immersive image viewer + evidence layer</p><h2 className="mission-section-heading mt-3 text-white">See what supports the answer.</h2></div>{result ? <div className="flex gap-2"><span className={pill(result.status)}>{formatLabel(result.status)}</span><button className="mission-button" onClick={downloadReport}><ArrowDownToLine className="size-4" /> Export report</button></div> : <span className="status-pill status-muted">Mission ready</span>}</div><div className="grid gap-5 xl:grid-cols-[1.16fr_.84fr]"><div className="mission-panel overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-cyan-100/10 p-4"><div className="flex flex-wrap gap-2">{([{ id: "optical", label: "Optical", icon: Globe2 }, { id: "sar", label: "SAR", icon: Radar }, { id: "change", label: "Change layer", icon: Waves }] as const).map((layer) => <button key={layer.id} onClick={() => setViewerLayer(layer.id)} className={`status-pill ${viewerLayer === layer.id ? "status-blue" : "status-muted"}`}><layer.icon className="size-3" />{layer.label}</button>)}</div><div className="flex items-center gap-3"><span className="mission-mono text-[8px] text-slate-500">Overlay</span><input aria-label="Evidence overlay opacity" className="accent-cyan-200" type="range" min="0" max="100" value={overlayOpacity} onChange={(event) => setOverlayOpacity(Number(event.target.value))} /></div></div><div className="viewer-scan mission-grid relative aspect-[1.18/1] overflow-hidden bg-[#030d16]"><img src={activeViewer} alt={`${formatLabel(viewerLayer)} satellite-viewer layer`} className="size-full object-cover opacity-90" />{result?.evidence.length ? <><div className="absolute inset-0 bg-cyan-400/10 mix-blend-screen" style={{ opacity: overlayOpacity / 100 }} /><div className="absolute left-[18%] top-[22%] h-[32%] w-[37%] border-2 border-cyan-200 bg-cyan-300/10" style={{ opacity: overlayOpacity / 100 }}><span className="absolute -top-7 left-0 whitespace-nowrap bg-cyan-200 px-2 py-1 mission-mono text-[9px] font-bold text-[#071421]">{result.evidence[0]?.region ?? "Evidence zone"}</span></div></> : null}<div className="absolute bottom-4 left-4 border border-cyan-100/25 bg-[#071827]/85 px-3 py-2 backdrop-blur"><p className="mission-mono text-[8px] tracking-widest text-cyan-100/80">{viewerLayer === "sar" ? "Sentinel-1 / SAR scene" : viewerLayer === "change" ? "Bi-temporal change view" : "Optical observation"}</p><p className="mt-1 text-xs text-slate-300">Grid · scale · evidence overlay ready</p></div><div className="absolute right-4 top-4 grid gap-2"><button className="grid size-8 place-items-center border border-cyan-100/25 bg-[#071827]/85 text-cyan-100"><Crosshair className="size-3.5" /></button><button className="grid size-8 place-items-center border border-cyan-100/25 bg-[#071827]/85 text-cyan-100"><Grid3X3 className="size-3.5" /></button><button className="grid size-8 place-items-center border border-cyan-100/25 bg-[#071827]/85 text-cyan-100"><MapPinned className="size-3.5" /></button></div></div><div className="grid grid-cols-3 divide-x divide-cyan-100/10 border-t border-cyan-100/10"><div className="p-3"><p className="mission-mono text-[8px] text-slate-500">Layer</p><p className="mt-1 text-xs font-bold text-white">{formatLabel(viewerLayer)}</p></div><div className="p-3"><p className="mission-mono text-[8px] text-slate-500">Evidence</p><p className="mt-1 text-xs font-bold text-white">{result?.evidence.length ?? 0} region(s)</p></div><div className="p-3"><p className="mission-mono text-[8px] text-slate-500">Viewer</p><p className="mt-1 text-xs font-bold text-white">Overlay {overlayOpacity}%</p></div></div></div>
          <div className="mission-panel p-5 sm:p-6">{!result ? <div className="flex min-h-[390px] flex-col justify-between"><div><p className="mission-kicker">Evidence panel</p><h3 className="mt-3 text-2xl font-bold tracking-tight text-white">Waiting for a mission result.</h3><p className="mission-copy mt-4">When analysis completes, GeoSaarthi will present the answer with confidence, evidence references, model provenance, limitations, and the full visible execution path.</p></div><div className="space-y-3">{["Validate Earth-observation assets", "Classify the request", "Select a compatible specialist", "Package evidence and confidence"].map((line, index) => <div key={line} className="flex gap-3 border-l border-cyan-100/15 pl-3"><span className="mission-mono text-[10px] text-cyan-200">0{index + 1}</span><p className="text-xs text-slate-400">{line}</p></div>)}</div></div> : <div><div className="flex flex-col justify-between gap-5 sm:flex-row"><div><p className="mission-kicker">{formatLabel(result.task)} / result</p><h3 className="mt-3 text-xl font-bold leading-7 text-white">{result.answer}</h3></div><div className="confidence-orb shrink-0" style={{ "--confidence": result.confidence } as React.CSSProperties}><div><p className="text-2xl font-bold text-cyan-100">{result.confidence}</p><p className="mission-mono text-[8px] text-slate-400">{result.confidenceLabel}</p></div></div></div><div className="mt-5 border-l-2 border-amber-200/70 bg-amber-200/[.05] px-3 py-2 text-xs leading-5 text-amber-100/80">{result.confidenceNote}</div><div className="mt-5"><p className="mission-kicker">Evidence references</p><div className="mt-3 space-y-2">{result.evidence.length ? result.evidence.map((evidence) => <button key={evidence.id} onClick={() => setOverlayOpacity(85)} className="flex w-full items-start gap-3 border border-cyan-100/12 bg-[#081c2e]/70 p-3 text-left transition-colors hover:border-cyan-200/40"><Crosshair className="mt-0.5 size-4 shrink-0 text-cyan-200" /><span><span className="block text-xs font-bold text-slate-100">{evidence.title}</span><span className="mt-1 block text-xs leading-5 text-slate-400">{evidence.summary}</span></span><ChevronRight className="ml-auto mt-1 size-4 text-slate-500" /></button>) : <p className="border border-dashed border-amber-200/20 p-3 text-xs leading-5 text-amber-100/70">Evidence is unavailable because the input requires correction or the request is outside the bounded workflow set.</p>}</div></div><div className="mt-5 grid gap-3 border-t border-cyan-100/10 pt-5 sm:grid-cols-2"><div><p className="mission-mono text-[8px] text-slate-500">Source</p><p className="mt-1 text-xs font-semibold text-slate-200">{result.provenance.source}</p></div><div><p className="mission-mono text-[8px] text-slate-500">Model bundle</p><p className="mt-1 text-xs font-semibold text-slate-200">{result.provenance.modelBundle}</p></div></div></div>}</div></div></div></section>

      <section id="demos" className="scroll-mt-16 px-5 py-20 md:px-8"><div className="mx-auto max-w-[1500px]"><div className="mb-8 flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><p className="mission-kicker">Demo laboratory</p><h2 className="mission-section-heading mt-3 text-white">Judge-ready missions. No hidden developer action.</h2></div><p className="mission-copy max-w-md text-xs">Each scripted benchmark case provides the input metadata, question, expected workflow, trace, evidence state, and report export pathway required for the bounded MVP.</p></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">{demoCases.data?.map((demo, index) => <button key={demo.id} onClick={() => loadDemo(demo.id)} className="mission-panel group p-4 text-left transition-transform duration-200 hover:-translate-y-1 hover:border-cyan-200/40"><div className="flex items-center justify-between"><span className="mission-mono text-[10px] text-cyan-200">Mission 0{index + 1}</span><ArrowRight className="size-4 text-slate-500 transition-transform group-hover:translate-x-1 group-hover:text-cyan-200" /></div><p className="mt-7 text-base font-bold text-white">{demo.title}</p><p className="mt-2 min-h-10 text-xs leading-5 text-slate-400">{demo.subtitle}</p><div className="mt-6 flex items-center justify-between border-t border-cyan-100/10 pt-3"><span className="status-pill status-blue">{demo.workflow}</span><span className="mission-mono text-[8px] text-slate-500">{formatLabel(demo.mode)}</span></div></button>)}</div><div className="mt-4 flex flex-wrap gap-3"><button className="mission-button" onClick={() => { setUiMode("single"); setAssets([]); setQuery("What changed between these dates?"); goto("console"); }}>Inspect missing pair <CircleAlert className="size-4 text-amber-200" /></button><button className="mission-button" onClick={() => { loadDemo("landcover-vqa"); setQuery("Describe this blurry, uncertain scene with low confidence."); }}>Inspect uncertainty <Activity className="size-4 text-amber-200" /></button></div></div></section>

      <section id="workflows" className="mission-grid scroll-mt-16 border-y border-cyan-100/10 bg-[#061727] px-5 py-20 md:px-8"><div className="mx-auto max-w-[1500px]"><div className="mb-8"><p className="mission-kicker">Agent visualization / specialist ecosystem</p><h2 className="mission-section-heading mt-3 text-white">The route is visible, not magical.</h2><p className="mission-copy mt-4 max-w-2xl">GeoSaarthi makes each transition inspectable: the query classifier identifies a supported task, the workflow router tests available inputs, a specialist adapter responds, and the evidence and confidence engines package a reviewable output.</p></div><div className="grid gap-5 xl:grid-cols-[.72fr_1.28fr]"><div className="mission-panel p-5"><p className="mission-mono text-[9px] tracking-widest text-cyan-200">Live routing chain</p><div className="mt-5 space-y-0">{["User query", "Query classifier", "Workflow router", "Specialist AI", "Geospatial engine", "Evidence engine", "Confidence engine", "Final answer"].map((label, index) => <button key={label} onClick={() => toast.message(`${label}: ${index < 2 ? "task and input requirements inspected" : index === 3 ? "registered adapter selected" : "visible in the execution trace after analysis"}`)} className="trace-line block w-full pb-5 pl-5 text-left last:pb-0"><span className="mission-mono text-[9px] text-slate-500">0{index + 1}</span><span className="ml-3 text-sm font-semibold text-slate-100">{label}</span></button>)}</div></div><div className="mission-panel overflow-hidden"><div className="grid grid-cols-[1.15fr_.9fr_.72fr] border-b border-cyan-100/10 bg-[#061828]/80 px-5 py-3 mission-mono text-[9px] tracking-widest text-slate-500"><span>Specialist</span><span>Task</span><span>Readiness</span></div>{registry.data?.map((tool) => <details key={tool.id} className="border-b border-cyan-100/10 last:border-b-0"><summary className="grid cursor-pointer grid-cols-[1.15fr_.9fr_.72fr] items-center gap-2 px-5 py-4 marker:hidden"><span><span className="block text-sm font-bold text-white">{tool.name}</span><span className="mission-mono mt-1 block text-[8px] text-slate-500">{tool.version}</span></span><span className="text-xs text-slate-400">{tool.tasks.map(formatLabel).join(", ")}</span><span className="status-pill status-good">Ready</span></summary><div className="grid gap-4 border-t border-cyan-100/10 bg-[#061827]/70 px-5 py-4 text-xs leading-5 text-slate-400 md:grid-cols-3"><p><b className="text-slate-100">Accepted input</b><br />{tool.acceptedInputs}</p><p><b className="text-slate-100">Benchmark path</b><br />{tool.data}</p><p><b className="text-slate-100">Known limitation</b><br />{tool.limitation}</p></div></details>)}</div></div></div></section>

      <section id="judge" className="scroll-mt-16 px-5 py-20 md:px-8"><div className="mx-auto max-w-[1500px]"><div className="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="mission-kicker">Judge mode / observability</p><h2 className="mission-section-heading mt-3 text-white">Open the system. Inspect the proof.</h2></div><span className="status-pill status-good"><ShieldCheck className="size-3" /> Responsible AI boundary</span></div><div className="grid gap-5 xl:grid-cols-[.95fr_1.05fr]"><div className="mission-panel p-5"><div className="flex items-center justify-between"><div><p className="mission-mono text-[9px] tracking-widest text-cyan-200">Latest analysis trace</p><p className="mt-2 text-lg font-bold text-white">{result ? result.runId : "No active run"}</p></div><Network className="size-6 text-cyan-200" /></div><div className="mt-6 space-y-0">{result ? result.trace.map((step, index) => <div key={`${step.label}-${index}`} className="trace-line pb-5 pl-5 last:pb-0"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-bold text-slate-100">{step.label}</p><span className={pill(step.status)}>{step.status}</span><span className="mission-mono text-[9px] text-slate-500">{step.elapsedMs} ms</span></div><p className="mt-1 text-xs leading-5 text-slate-400">{step.detail}</p></div>) : <div className="border border-dashed border-cyan-100/20 p-4 text-xs leading-5 text-slate-400">Run a demo mission to reveal timestamps, selected tools, execution steps, latency, evidence, confidence, and limitations.</div>}</div></div><div className="mission-panel overflow-hidden"><div className="flex items-center justify-between border-b border-cyan-100/10 p-5"><div><p className="mission-mono text-[9px] tracking-widest text-cyan-200">Analysis history</p><p className="mt-2 text-lg font-bold text-white">Metadata-only records</p></div><Database className="size-5 text-cyan-200" /></div><div className="overflow-x-auto"><table className="min-w-full text-left"><thead className="border-b border-cyan-100/10 bg-[#061828]/70"><tr className="mission-mono text-[8px] tracking-widest text-slate-500"><th className="px-5 py-3">Run</th><th className="px-5 py-3">Workflow</th><th className="px-5 py-3">Status</th><th className="px-5 py-3">Confidence</th></tr></thead><tbody>{recentRuns.data?.length ? recentRuns.data.map((run) => <tr key={run.runId} className="border-b border-cyan-100/10 text-xs last:border-b-0"><td className="px-5 py-4"><p className="font-bold text-slate-100">{run.runId}</p><p className="mt-1 max-w-36 truncate text-[10px] text-slate-500">{run.query}</p></td><td className="px-5 py-4 text-slate-300">{formatLabel(run.task)}</td><td className="px-5 py-4"><span className={pill(run.status)}>{formatLabel(run.status)}</span></td><td className="px-5 py-4 font-bold text-cyan-100">{run.overallConfidence}/100</td></tr>) : <tr><td colSpan={4} className="px-5 py-10 text-center text-xs text-slate-500">Your mission records will appear here after analysis. Raw image bytes are never stored.</td></tr>}</tbody></table></div></div></div><div className="mt-5 grid gap-3 md:grid-cols-3">{[{ icon: ShieldCheck, title: "AI-assisted interpretation", copy: "Not a certified operational decision for disaster, defence, or public safety." }, { icon: FileText, title: "Benchmark provenance", copy: "Public demo assets guide the interface; undisclosed ISRO/SAC evaluation labels are never assumed." }, { icon: PanelRightClose, title: "Bounded MVP", copy: "Input rejection, low confidence, and known limitations stay part of the user-facing result." }].map((item) => <div key={item.title} className="border border-cyan-100/12 bg-cyan-300/[.035] p-4"><item.icon className="size-5 text-amber-200" /><p className="mt-4 text-sm font-bold text-white">{item.title}</p><p className="mt-2 text-xs leading-5 text-slate-400">{item.copy}</p></div>)}</div></div></section>
      <section id="observatory" className="mission-grid scroll-mt-16 border-t border-cyan-100/10 bg-[#051827] px-5 py-20 md:px-8"><div className="mx-auto max-w-[1500px]"><div className="mb-8 flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><p className="mission-kicker">Mission telemetry + benchmark observatory</p><h2 className="mission-section-heading mt-3 text-white">Observe the demo. Separate signals from claims.</h2><p className="mission-copy mt-4 max-w-2xl">The satellite card is an explicit visual simulation. The benchmark registry represents scripted workflow coverage. Only the run metrics are calculated from metadata actually recorded by this workspace.</p></div><div className="flex flex-wrap gap-2"><span className="status-pill status-warn"><CircleAlert className="size-3" /> Telemetry simulated</span><span className="status-pill status-blue"><Database className="size-3" /> {recordedRuns.length} run records</span></div></div><div className="grid gap-5 xl:grid-cols-[.75fr_1.25fr]"><div className="mission-panel overflow-hidden"><div className="flex items-center justify-between border-b border-cyan-100/10 p-5"><div><p className="mission-mono text-[9px] tracking-widest text-cyan-200">Satellite control card</p><p className="mt-2 text-lg font-bold text-white">GS-DEMO-01</p></div><Satellite className="size-6 text-cyan-200" /></div><div className="p-5"><p className="mission-mono text-[9px] tracking-widest text-amber-200">Mission simulator · not a live feed</p><div className="mt-4 grid grid-cols-2 gap-3">{[{ l: "Mission", v: "Benchmark orbit" }, { l: "Sensor", v: "Optical + SAR" }, { l: "Altitude", v: "612 km" }, { l: "Velocity", v: "7.4 km/s" }, { l: "Latitude", v: telemetry.latitude }, { l: "Longitude", v: telemetry.longitude }, { l: "Heading", v: telemetry.heading }, { l: "Next pass", v: telemetry.nextPass }].map((item) => <div key={item.l} className="border border-cyan-100/10 bg-[#071b2c]/65 p-3"><p className="mission-mono text-[8px] tracking-widest text-slate-500">{item.l}</p><p className="mt-2 text-xs font-bold text-slate-100">{item.v}</p></div>)}</div><div className="mt-4 flex items-center justify-between border border-cyan-100/12 bg-cyan-300/[.05] p-3"><span className="flex items-center gap-2 text-xs font-bold text-emerald-100"><i className="signal-dot" /> Signal {telemetry.signal}</span><button onClick={() => setTelemetryFrame((frame) => (frame + 1) % telemetryFrames.length)} className="mission-button min-h-8 px-3 text-[9px]">Watch pass <ArrowRight className="size-3" /></button></div></div></div><div className="mission-panel p-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><p className="mission-mono text-[9px] tracking-widest text-cyan-200">Benchmark center</p><p className="mt-2 text-lg font-bold text-white">Coverage across the four SIH workflows</p></div><span className="status-pill status-good"><Check className="size-3" /> 4 / 4 staged</span></div><div className="mt-5 grid gap-2 md:grid-cols-2">{demoCases.data?.map((demo, index) => <button key={demo.id} onClick={() => loadDemo(demo.id)} className="border border-cyan-100/10 bg-[#071b2c]/65 p-3 text-left transition-colors hover:border-cyan-200/45"><div className="flex items-center justify-between"><span className="mission-mono text-[9px] text-cyan-200">CASE 0{index + 1}</span><ChevronRight className="size-4 text-slate-500" /></div><p className="mt-3 text-sm font-bold text-white">{demo.title}</p><p className="mt-2 text-xs text-slate-400">Expected route: {demo.workflow}</p><div className="mt-3 flex items-center justify-between border-t border-cyan-100/10 pt-3"><span className="mission-mono text-[8px] text-slate-500">{formatLabel(demo.mode)}</span><span className="status-pill status-blue">Ready</span></div></button>)}</div><div className="mt-5 grid gap-2 sm:grid-cols-3">{[{ l: "Recorded runs", v: String(recordedRuns.length), note: "Metadata rows" }, { l: "Success states", v: String(successfulRuns), note: "Status = success" }, { l: "Average confidence", v: averageConfidence === null ? "—" : `${averageConfidence}/100`, note: "Recorded runs only" }].map((metric) => <div key={metric.l} className="border border-cyan-100/10 bg-[#061625]/70 p-3"><p className="mission-mono text-[8px] tracking-widest text-slate-500">{metric.l}</p><p className="mt-2 text-2xl font-bold text-cyan-100">{metric.v}</p><p className="mt-1 text-[10px] text-slate-500">{metric.note}</p></div>)}</div></div></div><div className="mt-5 grid gap-5 xl:grid-cols-[.65fr_.9fr_.45fr]"><div className="mission-panel p-5"><p className="mission-kicker">Mission feed</p><div className="mt-4 space-y-0">{missionFeed.map((item, index) => <div key={item} className="trace-line pb-4 pl-5 last:pb-0"><p className="mission-mono text-[8px] text-slate-500">SIM-{String(index + 1).padStart(2, "0")}</p><p className="mt-1 text-xs text-slate-300">{item}</p></div>)}</div></div><div className="mission-panel p-5"><p className="mission-kicker">Evaluation boundary</p><p className="mt-3 text-sm font-bold text-white">No invented live benchmark score.</p><p className="mission-copy mt-3 text-xs">Scripted-demo readiness, declared workflow coverage, and collected run metadata are shown separately. Any real accuracy, latency, or operational performance claim requires a reproducible evaluation plan and relevant dataset labels.</p></div><div className="mission-panel p-5"><p className="mission-kicker">Review queue</p><p className="mt-3 text-3xl font-bold text-amber-200">{reviewRuns}</p><p className="mt-2 text-xs leading-5 text-slate-400">Recorded runs that require review, including low-confidence and rejected-input states.</p></div></div></div></section>
    </main>
    <footer className="border-t border-cyan-100/10 bg-[#04111d] px-5 py-8 md:px-8"><div className="mx-auto flex max-w-[1500px] flex-col justify-between gap-4 text-xs text-slate-500 md:flex-row md:items-center"><div className="flex items-center gap-3"><Orbit className="size-4 text-cyan-200" /><span><b className="text-slate-200">GeoSaarthi</b> · Bounded SIH26167 prototype</span></div><div className="mission-mono text-[8px] tracking-[.13em]">Evidence before eloquence · Team getunlockD.I</div></div></footer>
  </div>;
}
